// ═══════════════════════════════════════════════════════
// DYNAMIC EXECUTOR — Low-code Engine
// Không hardcode tên API hay tham số.
// Chỉ cần: ApiCode + params (JSON object tự do)
// ═══════════════════════════════════════════════════════
const raw = $input.item.json;
const body = raw.body || raw;
const headers = raw.headers || {};

const ApiCode = (body.ApiCode || '').trim();
const username = body.username || 'default';
const token = headers.authorization || body.token || 'Bearer empty';
const isConfirm = parseInt(body.isConfirm || '0', 10);

// params: AI Agent truyền lên dưới dạng JSON string hoặc object
let params = {};
if (typeof body.params === 'string') {
  try { params = JSON.parse(body.params); } catch(e) { params = {}; }
} else if (typeof body.params === 'object' && body.params !== null) {
  params = body.params;
}

// Inject @Username tự động (theo n8n-config.md)
if (!params['@Username']) {
  params['@Username'] = username;
}

if (!ApiCode) {
  return [{ json: {
    loi: true,
    message: 'Thiếu ApiCode. Gửi kèm params là JSON object với các key dạng @ParamName.'
  }}];
}

return [{ json: {
  ApiCode,
  username,
  token,
  isConfirm,
  params,
  hop_le: true
}}];

const data = $input.item.json;
const ApiCode = $('Parse Input').item.json.ApiCode || '';

if (data.error || data.status === 'error') {
  return [{ json: {
    ket_qua: `❌ Lỗi [${ApiCode}]: ${data.message || data.error || 'Lỗi không xác định'}`,
    loi: true
  }}];
}

const payload = data.data || data.result || data.message || data;
let text = '';

if (typeof payload === 'string') {
  text = payload;
} else if (Array.isArray(payload)) {
  const total = payload.length;
  text = `Tìm thấy ${total} kết quả:\n` +
    payload.slice(0, 20).map((row, i) => {
      const vals = Object.entries(row)
        .filter(([k]) => !k.startsWith('_'))
        .map(([k, v]) => `${k}: ${v}`).join(' | ');
      return `${i + 1}. ${vals}`;
    }).join('\n');
  if (total > 20) text += `\n... và ${total - 20} kết quả khác.`;
} else {
  text = JSON.stringify(payload, null, 2);
}

return [{ json: {
  ket_qua: text || 'Không có dữ liệu.',
  ApiCode,
  so_ban_ghi: Array.isArray(payload) ? payload.length : null
}}];

const data = $input.item.json;
return [{ json: {
  ket_qua: data.message || 'Yêu cầu không hợp lệ.',
  loi: true
}}];
